def ip_to_bin(ip):
    return ".".join(f"{int(part):08b}" for part in ip.split("."))

def ip_to_int(ip):
    value = 0
    for part in ip.split("."):
        value = (value << 8) | int(part)
    return value

def flip_case(text):
    out = []
    for ch in text:
        if "a" <= ch <= "z" or "A" <= ch <= "Z":
            out.append(chr(ord(ch) ^ 0x20))
        else:
            out.append(ch)
    return "".join(out)
